## 2️⃣ Backend (Node.js + Express)

### 2.1 Instalar dependências

```bash
mkdir my-pix-system && cd my-pix-system
npm init -y
npm install express express-session body-parser axios dotenv
```

### 2.2 Criar `.env` (arquivo de variáveis)

```text
PORT=3000
LED_PORT=8088
LED_PIN=5   # GPIO pin para NeoPixel (depende do seu hardware)
MERCADO_PAGO_API_KEY=YOUR_MARKET_PAYGAS_API_KEY
MERCADO_PAGO_SECRET=YOUR_MERCADO_PAGO_SECRET
```

### 2.3 `server.js`

```js
// server.js
require('dotenv').config();
const express = require('express');
const session = require('express-session');
const bodyParser = require('body-parser');
const axios = require('axios');

const app = express();
app.use(session({ secretToken: 'your_session_secret', resave: false, saveUninitialized: true }));
app.use(bodyParser.json());

// Simulação de leitura de banco (pode ser real DB)
let messages = []; // array of last 3 messages
let sponsors = {}; // key: name, value: rank

// ---------- Helpers ----------
function generateQrCode() {
  // Aqui você pode usar library 'qrcode' ou gerar via API.
  // Exemplo rápido com node-qrcode:
  const { QRCode } = require('node-qrcode');
  return QRCode.toDataURL('https://example.com/qr?msg=' + Date.now());
}

// ---------- Routes ----------

// 1) Home page (index.html)
app.get('/', (req, res) => {
  const qrUrl = generateQrCode(); // gera URL do QR Code
  res.send(`
    <!DOCTYPE html>
    <html lang="pt-BR">
    <head>
      <meta charset="UTF-8">
      <title>Sistema de Pix</title>
      <style>
        body { font-family: Arial, sans-serif; text-align: center; background:#222; color:#fff; }
        .container { margin-top: 50px; }
        button { padding: 10px 20px; font-size: 16px; cursor: pointer; }
      </style>
    </head>
    <body>
      <div class="container">
        <h1>🎉 Sistema de Convidados & Pix</h1>
        <p>Escaneie o QR Code abaixo para entrar no formulário.</p>
        <img src="${qrUrl}" alt="QR Code" style="margin-bottom:20px;">
        <form id="invitation-form">
          <label for="name">Nome:</label><br>
          <input type="text" id="name" required><br><br>
          <label for="message">Mensagem:</label><br>
          <textarea id="message" rows="4" required></textarea><br><br>
          <button type="submit">Enviar Pix</button>
        </form>
        <h2>Patrocinadores (Top)</h2>
        <pre id="sponsors"></pre>
        <h2>Últimas 3 Mensagens</h2>
        <ul id="messages"></ul>
      </div>
    </body>
    </html>
  `);
});

// 2) Form submission (POST /invitation-form)
app.post('/invitation-form', async (req, res) => {
  const { name, message } = req.body;
  // Simula envio de Pix via Mercado Pago (API call)
  try {
    await axios.post(
      'https://api.marketpayg.com/v1/payments',
      { amount: 1000, currency: 'BRL', token: 'YOUR_TOKEN_HERE', ... },
      { headers: { Authorization: `Bearer ${process.env.MERCADO_PAGO_API_KEY}` } }
    );
    // Após sucesso, "envia pix"
    // Atualiza mensagens e ranking aqui...
    // Exemplo: adiciona nova mensagem ao array
    messages.push(`[${new Date().toISOString()}] ${name}: "${message}"`);
    // Mantém apenas as 3 mais recentes
    if (messages.length > 3) messages.shift();

    // Atualiza UI
    document.getElementById('messages').innerHTML = `
      <ul>
        ${messages.slice(-3).map((m, i) => `<li>${m}</li>`).join('')}
      </ul>
    `;

    // Ranking de patrocinadores (simples)
    const topSponsor = 'Influenciador';
    sponsors.topSponsor = 'Influenciador'; // placeholder
    document.getElementById('sponsors').innerText = `Top Patrocinador: ${topSponsor} (${1})`;
    res.send(`<h2>Patrocinadores: Top ${sponsors.topSponsor}</h2><pre>${document.getElementById('sponsors').innerText}</pre>`);

    // Redireciona para LED display (opcional)
    res.redirect(`http://localhost:${LED_PORT}/led`);
  } catch (err) {
    console.error(err);
    res.status(500).send('Erro ao enviar Pix');
  }
});

// 3) GET /led (para controlar LEDs)
app.get('/led', (req, res) => {
  // Aqui você conecta NeoPixel via GPIO (ex.: using 'neopixel' lib)
  // Retorna estado atual dos LEDs
  res.send('<status>LED display ready</status>');
});

// Start server
app.listen(process.env.PORT, () => {
  console.log(`Servidor rodando na porta ${process.env.PORT}`);
});
```

> **Importante:** Substitua `YOUR_TOKEN_HERE` pela chave do Mercado Pago quando configurar a chamada de pagamento.

